      const huns = list.map((name) => game.createCard(`huashen_card_${name}`, " ", " "));
      await player.showCards(huns, `${get.translation(player)}发动了〖${get.translation(event.name)}〗`);
      const result = await player.chooseToMove_new({
        prompt: "著魂",
        forced: true,
        list: [
          ["你的手牌", player.getCards("h")],
          ["魂对应的卡牌", []],
          ["魂", huns]
        ],
        huns,
        num,
        filterMove(from, to, moved) {
          const { huns: huns2, player: player2 } = get.event();
          if (from?.link && huns2.includes(from.link) && typeof to == "number") {
            return false;
          }
          if (from?.link && huns2.includes(from.link) && to?.link && player2.getCards("h").includes(to.link)) {
            return false;
          }
          return true;
        },
        filterOk(moved) {
          const { num: num2, huns: huns2 } = get.event();
          if ([moved[1], moved[0]].some((move) => move.containsSome(...huns2))) {
            return false;
          }
          return moved?.[1]?.length == num2;
        },
        processAI(list2) {
          const { player: player2, huns: huns2, num: num2 } = get.event();
          const cards2 = player2.getCards("h");
          cards2.sort((a, b) => get.value(a) - get.value(b));
          const cardx = cards2.slice(num2);
          return [cards2.removeArray(cardx), cardx, huns2];
        }
      }).forResult();
      if (result?.bool && result.moved?.length) {
        const moved = result.moved;
        const cards2 = moved?.[1], huns2 = moved?.[2];
        if (huns2?.length) {
          player.setStorage(event.name, [huns2, []], true);
        }
        if (cards2?.length) {
          await player.addToExpansion({ cards: cards2.reverse(), source: player, animate: "give", gaintag: [event.name] });
        }
      }
    },
    addVisitors(characters2, player) {
      _status.characterlist.removeArray(characters2);
      game.log(player, "将", "#y" + get.translation(characters2), "加入了", "#g“著魂”");
      game.broadcastAll(
        (player2, characters3) => {
          player2.tempname.addArray(characters3);
          player2.$draw(
            characters3.map((name) => {
              const cardname = "huashen_card_" + name;
              const skills2 = get.character(name, 3) ?? [];
              const translates2 = skills2.map((skill) => `${lib.translate[skill]}：${lib.translate[skill + "_info"]}`).join("<br>");
              lib.card[cardname] = {
                fullimage: true,
                image: "character:" + name,
                skills: []
              };
              lib.translate[cardname] = get.slimName(name);
              lib.translate[`${cardname}_info`] = translates2;
              return game.createCard(cardname, " ", " ");
            }),
            "nobroadcast"
          );
        },
        player,
        characters2
      );
    },
    removeVisitors(characters2, player) {
      if (Array.isArray(player.tempname)) {
        game.broadcastAll((player2, characters3) => player2.tempname.removeArray(characters3), player, characters2);
      }
      const storage = player.getStorage("ymzhuhun");
      player.setStorage("ymzhuhun", [storage[0].slice(0).removeArray(characters2), storage[1]], true);
