      const cards2 = player.getExpansions(skill);
      if (cards2.length) {
        player.loseToDiscardpile({ cards: cards2 });
      }
      const characters2 = player.storage[skill]?.[0]?.map((card) => card.name.replace("huashen_card_", ""));
      if (characters2?.length) {
        get.info(skill).removeVisitors(characters2, player);
      }
      const characterx = player.storage[skill]?.[1]?.map((card) => card.name.replace("huashen_card_", ""));
      if (characterx?.length) {
        get.info(skill).removeVisitors(characterx, player);
      }
