    filter(event, player) {
      return player !== event.player && player.storage.ymzhuhun?.[0]?.length;
    },
    popup: false,
    async cost(event, trigger, player) {
      const target = trigger.player;
      const storage = player.storage.ymzhuhun, cards2 = player.getExpansions("ymzhuhun");
      if (!storage?.[0]?.length) {
        return;
      }
      const createDialog = ["经世：你可以根据卡牌提示选择一张武将牌", [[storage[0], "card"]]];
      if (cards2.length) {
        createDialog[1].push(cards2.slice(0).randomSort());
      }
      if (cards2.length < storage[0].length) {
        createDialog[1].push([[["nocard", "此武将牌上没有放牌"]], "tdnodes"]);
      }
      const numx = Math.max(1, storage[0].length - cards2.length);
      const result = await target.chooseButton({
        createDialog,
        filterButton(button) {
          const { cards: cards3 } = get.event();
          if (!ui.selected.buttons?.length) {
            return cards3.includes(button.link) || button.link === "nocard";
          }
          return !cards3.includes(button.link) && button.link !== "nocard";
        },
        selectButton: 2,
        ai(button) {
          const { player: player2, target: target2, storage: storage2 } = get.event();
          if (get.attitude(player2, target2) > 0 || storage2?.[0].length > 1) {
            return 1 + Math.random();
          }
          return 0;
        }
      }).set("storage", storage).set("target", player).set("cards", cards2).forResult();
      if (result?.bool && result.links?.length) {
        event.result = {
          bool: true,
          cost_data: [result.links, numx]
        };
      }
    },
    async content(event, trigger, player) {
      const target = trigger.player;
      target.logSkill(event.name, player);
      const {
        cost_data: [[link, hun], numx]
      } = event;
      const storage = player.storage.ymzhuhun, cards2 = player.getExpansions("ymzhuhun");
      const num = cards2.indexOf(link), card = cards2[num], anhun = storage[0][num];
      if (card) {
        await player.loseToDiscardpile({ cards: [card] });
      }
      get.info("ymzhuhun").removeVisitors([anhun], player);
      storage[0].remove(anhun);
      storage[1].push(anhun);
      player.setStorage("ymzhuhun", storage, true);
      let bool = false;
      if (hun == anhun) {
        if (num == -1 && link == "nocard" && Math.random() <= 1 / numx || card == link) {
          bool = true;
        }
      }
      if (bool) {
        player.popup("洗具");
        await player.draw(2);
