        const { player: card, targets: cards2 } = result;
        const list = cards2.filter((cardx) => get.position(cardx) === "d" && get.number(cardx) < get.number(card));
        if (list?.length) {
          await player.gain({
            cards: list,
            animate: "gain2"
          });
        }
        return;
      }
      const next = player.insertPhase();
      if (!trigger._finished) {
        trigger.finish();
        trigger._finished = true;
        trigger._triggered = 5;
        if (!lib.onround.includes(get.info("sm_xianxing").onRound)) {
          lib.onround.push(get.info("sm_xianxing").onRound);
        }
        const evt = trigger.player.insertPhase();
        evt.set("xianxing_phase", true);
        evt.relatedEvent = trigger.relatedEvent || trigger.getParent(2);
        evt.skill = trigger.skill;
        evt._noTurnOver = trigger._noTurnOver;
        evt.set("phaseList", trigger.phaseList);
        evt.pushHandler("xianxing_phase", (event2, option) => {
          if (event2.step === 0 && option.state === "begin") {
            event2.step = 2;
            _status.globalHistory.push({
              cardMove: [],
              custom: [],
              useCard: [],
              changeHp: [],
              everything: []
            });
            const players = game.players.slice(0).concat(game.dead);
            for (const current of players) {
              current.actionHistory.push({
                useCard: [],
                respond: [],
                skipped: [],
                lose: [],
                gain: [],
                sourceDamage: [],
                damage: [],
                custom: [],
                useSkill: []
              });
              current.stat.push({ card: {}, skill: {} });
            }
          }
        });
      }
      const nexts = trigger.getParent()?.next;
      if (nexts?.length) {
        for (const evt of nexts.slice(0)) {
          if (evt.finished) {
            continue;
          }
          if (evt === next) {
            break;
          }
          nexts.remove(evt);
          nexts.push(evt);
        }
      }
    }
  }

