{
    audio: "twzhian",
    trigger: {
      global: "useCardAfter"
    },
    filter(event, player) {
      if (get.type(event.card) === "basic") {
        return false;
      }
      return player.isDamaged() || player.countCards("h") || !player.hasSkill("yjzhian_delete");
    },
    usable(skill, player) {
      return Math.max(1, player.getDamagedHp());
    },
    async cost(event, trigger, player) {
      const cards2 = trigger.cards?.filterInD("ejod") || [];
      const list = ["选项一", "选项二", "选项三", "cancel2"];
      const choiceList = [`弃置一张手牌${cards2.length ? `并获得${get.translation(cards2)}` : ""}`, "回复1点体力，此技能本轮失效", `对${get.translation(trigger.player)}造成${get.cnNumber(Math.max(1, player.getDamagedHp()))}点伤害，获得〖飞影〗并删去此项`];
      let choice = "cancel2";
      if (player.isDamaged()) {
        if (player.hp <= 1) {
          choice = "选项二";
        }
      } else {
        list.remove("选项二");
        choiceList[1] = `<span style="opacity:0.5">${choiceList[1]}</span>`;
      }
      if (!player.countCards("h")) {
        list.remove("选项一");
        choiceList[0] = `<span style="opacity:0.5">${choiceList[0]}</span>`;
      } else {
        if (cards2.length && player.hp > 1) {
          let result2 = 0;
          const card = trigger.card;
          const owner = get.owner(card);
          if (owner) {
            if (get.position(card) === "j") {
              const vcard = { name: card.viewAs || card.name, cards: [card] };
              result2 += get.effect(player, vcard, player, player) * get.sgn(get.attitude(player, owner));
            } else {
              result2 += (get.value(card, owner) - 0.01) * get.sgn(get.attitude(player, owner));
            }
          } else {
            result2 += cards2.reduce((sum, i) => sum + get.value(i, player), 0);
          }
          result2 -= get.recoverEffect(player);
          if (result2 > player.getCards("h").map((i) => get.value(i)).minBy((i) => i)) {
            choice = "选项一";
          }
        }
      }
      if (player.hasSkill("yjzhian_delete")) {
        list.remove("选项三");
        choiceList[2] = `<span style="opacity:0.5">${choiceList[2]}</span>`;
      } else if (get.damageEffect(trigger.player, player) > 0 && choice === "cancel2") {
        choice = "选项三";
      }
      const result = await player.chooseControl(list).set("prompt", get.prompt(event.skill, trigger.player)).set("choiceList", choiceList).set("ai", () => get.event().choice).set("choice", choice).forResult();
      event.result = {
        bool: result.control !== "cancel2",
        cost_data: result.control,
        targets: [trigger.player]
      };
    },
    async content(event, trigger, player) {
      switch (event.cost_data) {
        case "选项一": {
          await player.chooseToDiscard("h", true);
          await player.gain(trigger.cards.filterInD("odej"), "gain2");
          break;
        }
        case "选项二": {
          await player.recover();
          player.tempBanSkill(event.name, "roundEnd");
          break;
        }
        case "选项三": {
          player.addSkill("yjzhian_delete");
          await trigger.player.damage(Math.max(1, player.getDamagedHp()));
          await player.addSkills("feiying");
        }
      }
    },
    subSkill: {
      delete: {
        charlotte: true
      }
    },
    derivation: "feiying"
  }

